# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_3_1_2_40_8", r"в учебнике функция задана условиями $x\ne\pi n$ и $x=\pi n$ (нули синуса); в условии $\pi$ была потеряна (OCR): при $x=n$ функция не определена в точках $\pi k$, $k\ne0$",
  q=r"Имеет ли точки разрыва функция: $y = \dfrac{|\sin x|}{\sin x}$, если $x \neq \pi n$ ($n \in \mathbb{Z}$); $0$, если $x = \pi n$ ($n \in \mathbb{Z}$)?")
E("G11_TB_4_2_4_8_4", r"$f'(x)=2x-1$; значения производной при $x=0;1;-1;2;-2;3;-3$: $-1;1;-3;3;-5;5;-7$ (в ключе стояли значения $4x-3$)",
  k=r"производная: $2x-1$; значения: $-1$; $1$; $-3$; $3$; $-5$; $5$; $-7$; равна $0$: $x=\dfrac{1}{2}$; равна $1$: $x=1$; равна $3$: $x=2$",
  dnew={0: (r"производная: $2x+1$; значения: $1$; $3$; $-1$; $5$; $-3$; $7$; $-5$; равна $0$: $x=-\dfrac{1}{2}$; равна $1$: $x=0$; равна $3$: $x=1$", r"Ученик посчитал производную от $-x$ равной $+1$ и получил $2x+1$."),
        1: (r"производная: $2x-1$; значения: $5$; $5$; $7$; $7$; $11$; $11$; $17$; равна $0$: $x=\dfrac{1}{2}$; равна $1$: $x=1$; равна $3$: $x=2$", r"Ученик вычислил значения самой функции $f(x)=x^{2}-x+5$, а не её производной."),
        2: (r"производная: $x-1$; значения: $-1$; $0$; $-2$; $1$; $-3$; $2$; $-4$; равна $0$: $x=1$; равна $1$: $x=2$; равна $3$: $x=4$", r"Ученик забыл множитель $2$ при дифференцировании $x^{2}$ и записал производную $x-1$.")})
